import React from 'react';
import PropTypes from 'prop-types';

import { MuiThemeProvider } from '@material-ui/core/styles';
import CssBaseline from '@material-ui/core/CssBaseline';

import getPageContext from './getPageContext';

function withMaterialUI(Component) {
  class WithMaterialUI extends React.PureComponent {
    constructor(props) {
      super(props);
      this.pageContext = getPageContext(props.currentTheme);
    }

    forceChangeTheme = false;

    componentDidMount() {
      // Remove the server-side injected CSS.
      const jssStyles = document.querySelector('#jss-server-side');
      if (jssStyles && jssStyles.parentNode) {
        jssStyles.parentNode.removeChild(jssStyles);
      }
    }

    componentWillReceiveProps(nextProps) {
      if (nextProps.currentTheme !== this.props.currentTheme) {
        this.forceChangeTheme = true;
        // MuiThemeProvider makes the theme available down the React tree thanks to React context.
        this.pageContext = getPageContext(
          nextProps.currentTheme,
          this.forceChangeTheme,
        );
      }
    }

    componentDidUpdate() {
      if (this.forceChangeTheme) {
        this.forceChangeTheme = false;
      }
    }

    render() {
      return (
        <MuiThemeProvider
          theme={this.pageContext.theme}
          //sheetsManager={this.pageContext.sheetsManager}
        >
          {/* CssBaseline kickstart an elegant, consistent, and simple baseline to build upon. */}
          <CssBaseline />
          <Component {...this.props} />
        </MuiThemeProvider>
      );
    }
  }

  WithMaterialUI.propTypes = {
    pageContext: PropTypes.object,
    currentTheme: PropTypes.string,
  };

  WithMaterialUI.getInitialProps = ctx => {
    if (Component.getInitialProps) {
      return Component.getInitialProps(ctx);
    }

    return {};
  };

  return WithMaterialUI;
}

export default withMaterialUI;
